module gnome_damage_calculator(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] n,\n    input [3:0] m,\n    input [7:0] k,\n    output reg [15:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] IDLE            = 4'd0;\n    localparam [3:0] CHECK_CONDITION = 4'd1;\n    localparam [3:0] INIT_T          = 4'd2;\n    localparam [3:0] CHECK_T         = 4'd3;\n    localparam [3:0] COMPUTE_BOUNDS  = 4'd4;\n    localparam [3:0] COMPUTE_D1_R    = 4'd5;\n    localparam [3:0] COMPUTE_A_B     = 4'd6;\n    localparam [3:0] COMPUTE_D2      = 4'd7;\n    localparam [3:0] COMPUTE_DAMAGE  = 4'd8;\n    localparam [3:0] UPDATE_BEST     = 4'd9;\n    localparam [3:0] NEXT_T          = 4'd10;\n    localparam [3:0] DONE_STATE      = 4'd11;\n\n    reg [3:0] state, next_state;\n    reg [3:0] t_reg;\n    reg [7:0] current_T;\n    reg first_T_flag;\n    reg [15:0] best_damage;\n    reg start_reg;\n\n    reg [15:0] D1_val;\n    reg [7:0] R_val;\n    reg [15:0] D2_val;\n    reg [15:0] damage_temp;\n\n    reg [7:0] L1_val, U1_val, L2_val, L_val, U_val;\n    reg [7:0] a_val, b_val;\n    reg [7:0] temp_n_minus_tk, temp_n_minus_t;\n\n    wire start_edge = start && !start_reg;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 16'd0;\n            t_reg <= 4'd0;\n            current_T <= 8'd0;\n            first_T_flag <= 1'b0;\n            best_damage <= 16'd0;\n            start_reg <= 1'b0;\n            D1_val <= 16'd0;\n            R_val <= 8'd0;\n            D2_val <= 16'd0;\n            damage_temp <= 16'd0;\n        end else begin\n            start_reg <= start;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start_edge) begin\n                        if (n <= {1'b0, m}) begin\n                            result <= (n * (n + 8'd1)) >> 1;\n                            state <= DONE_STATE;\n                        end else begin\n                            state <= CHECK_CONDITION;\n                        end\n                    end\n                end\n\n                CHECK_CONDITION: begin\n                    best_damage <= 16'd0;\n                    state <= INIT_T;\n                end\n\n                INIT_T: begin\n                    t_reg <= m;\n                    state <= CHECK_T;\n                end\n\n                CHECK_T: begin\n                    if (t_reg > m) begin\n                        state <= DONE_STATE;\n                    end else begin\n                        state <= COMPUTE_BOUNDS;\n                    end\n                end\n\n                COMPUTE_BOUNDS: begin\n                    // Compute L1\n                    temp_n_minus_tk = n - (t_reg * (k - 8'd1));\n                    if (n < (t_reg * (k - 8'd1))) temp_n_minus_tk = 8'd0;\n                    L1_val = (temp_n_minus_tk + k - 8'd1) / k;\n\n                    // Compute U1\n                    temp_n_minus_t = n - t_reg;\n                    if (n < t_reg) temp_n_minus_t = 8'd0;\n                    U1_val = temp_n_minus_t / k;\n\n                    // Compute L2\n                    L2_val = m - t_reg;\n\n                    // Compute L and U\n                    L_val = (L1_val > L2_val) ? L1_val : L2_val;\n                    U_val = U1_val;\n\n                    if (L_val <= U_val) begin\n                        current_T <= L_val;\n                        first_T_flag <= 1'b1;\n                        state <= COMPUTE_D1_R;\n                    end else begin\n                        state <= NEXT_T;\n                    end\n                end\n\n                COMPUTE_D1_R: begin\n                    D1_val <= (n * current_T) - ((k * current_T * (current_T - 8'd1)) >> 1);\n                    R_val <= n - (k * current_T);\n                    state <= COMPUTE_A_B;\n                end\n\n                COMPUTE_A_B: begin\n                    if (t_reg == 4'd0) begin\n                        a_val <= 8'd0;\n                        b_val <= 8'd0;\n                        state <= COMPUTE_D2;\n                    end else begin\n                        a_val <= R_val / t_reg;\n                        b_val <= R_val % t_reg;\n                        state <= COMPUTE_D2;\n                    end\n                end\n\n                COMPUTE_D2: begin\n                    if (t_reg == 4'd0) begin\n                        D2_val <= 16'd0;\n                    end else begin\n                        D2_val <= (a_val * t_reg * (t_reg + 4'd1) / 2) +\n                                  (b_val * (b_val + 8'd1) / 2);\n                    end\n                    state <= COMPUTE_DAMAGE;\n                end\n\n                COMPUTE_DAMAGE: begin\n                    damage_temp <= D1_val + D2_val;\n                    state <= UPDATE_BEST;\n                end\n\n                UPDATE_BEST: begin\n                    if (damage_temp > best_damage) begin\n                        best_damage <= damage_temp;\n                    end\n\n                    if (first_T_flag && (current_T != U_val)) begin\n                        current_T <= U_val;\n                        first_T_flag <= 1'b0;\n                        state <= COMPUTE_D1_R;\n                    end else begin\n                        state <= NEXT_T;\n                    end\n                end\n\n                NEXT_T: begin\n                    t_reg <= t_reg - 4'd1;\n                    state <= CHECK_T;\n                end\n\n                DONE_STATE: begin\n                    result <= best_damage;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule